# Architecture:
# Blackmacro leds use an effect layer system. Each layer transforms the existing LED data procedurally. The final result is then pushed to the led controller.
# Every frame, the led values would be generated by the first layer, then transformed by the second, then the third, and so on.
# e.g.: Rainbow background generator -> key state visualization -> key press visualization -> user brightness control -> powersave blackout => output
import neopixel
import machine
import hardware_defs


class LEDLayer:
    def process(self, data: list[tuple[int, int, int]]) -> list[tuple[int, int, int]]:
        pass

class RainbowGenerator(LEDLayer):
    def process(self, data: list[tuple[int, int, int]]) -> list[tuple[int, int, int]]:
        #TODO
        pass

# =====

class LEDController:
    def __init__(self):
        self.layers: list[LEDLayer] = []
        self.pin = machine.Pin(hardware_defs.P_LED, machine.Pin.OUT)
        self.leds = neopixel.NeoPixel(self.pin, hardware_defs.COUNT_LED)

    def update(self):
        data: list[tuple[int, int, int]] = [(0,0,0) for i in range(hardware_defs.COUNT_LED)]
        for layer in self.layers:
            data = layer.process(data)

        # push to leds
        self.leds.fill((0,0,0))
        for idx, val in enumerate(data):
            self.leds[idx] = (val[0], val[1], val[2])

        self.leds.write()